import {rimProfiles} from './tuning-rims.js?v=0.8.1';
import {TUNING_CATEGORIES,tuningQuote,TUNING_PRICES} from './tuning.js?v=0.8.1';
import {VEHICLES,euro} from './data.js?v=0.8.1';
const rimIcon=(id,type)=>{const style=id==='default'?(type==='sport'?'sport':'classic'):id;return '<svg viewBox="-1.08 -1.08 2.16 2.16" aria-hidden="true"><circle r=".98" fill="#14232b" stroke="#c6d0d0" stroke-width=".055"/>'+rimProfiles(style).map(poly=>'<polygon points="'+poly.map(p=>p.join(',')).join(' ')+'" fill="#adbabc" stroke="#d3dedf" stroke-width=".012"/>').join('')+'<circle r=".16" fill="#71828a" stroke="#bdcbcd" stroke-width=".025"/></svg>';};
const spoilerIcon=id=>'<svg viewBox="0 0 90 60" aria-hidden="true"><path d="M9 40V32L22 28L31 14H57L70 28H80V40Z" fill="#647d82"/><path d="M31 17H54L64 28H24Z" fill="#18313d"/><circle cx="24" cy="41" r="8" fill="#13232c"/><circle cx="67" cy="41" r="8" fill="#13232c"/>'+(id==='lip'?'<path d="M9 30H22" stroke="#dfbf80" stroke-width="4"/>':id==='touring'?'<path d="M11 29V21M20 29V21M5 20H25" stroke="#dfbf80" stroke-width="3"/>':'')+'</svg>';
export function tuningPanel(s,session,button){if(!session)return '<section class="tuning-ui"><p class="lead">Dein Fahrzeug, dein Stil.</p><p>Fahre deinen Kleinwagen, Lieferwagen oder dein Sportcoupé in die markierte Bucht. Folge dem Pfeil, halte an und steige aus. Eine grüne Markierung bestätigt die Ausrichtung.</p><p>Fahrräder können hier nicht angepasst werden.</p>'+button('Zurück','close','','secondary')+'</section>';
 const {vehicle,draft,tab}=session,options=TUNING_CATEGORIES[tab].options,quote=tuningQuote(vehicle.customization,draft);
 return '<section class="tuning-ui"><p class="tuning-vehicle">DEIN FAHRZEUG · '+VEHICLES[vehicle.id].name+'</p><div class="tabs">'+Object.entries(TUNING_CATEGORIES).map(([id,category])=>button(category.label,'tuningTab',id,id===tab?'active':'secondary')).join('')+'</div><div class="tuning-options">'+Object.entries(options).map(([id,o])=>'<button class="tuning-option '+(draft[tab]===id?'selected':'')+'" aria-pressed="'+(draft[tab]===id)+'" data-action="tuningOption" data-arg="'+tab+'|'+id+'">'+(tab==='rims'?rimIcon(id,vehicle.id):tab==='spoiler'?spoilerIcon(id):'<i style="background:#'+(o.color??session.mesh.userData.defaultPaint??0x447c84).toString(16).padStart(6,'0')+'"></i>')+'<span>'+o.name+'</span></button>').join('')+'</div><p class="tuning-selection">Ausgewählt: <b>'+options[draft[tab]].name+'</b></p><div class="tuning-cost"><b>Änderungen</b>'+(quote.changes.length?quote.changes.map(k=>'<div><span>'+TUNING_CATEGORIES[k].name+'</span><span>'+euro(TUNING_PRICES[k])+'</span></div>').join(''):'<p>Keine Änderungen</p>')+'</div><p class="footnote">Vorschau direkt an deinem Fahrzeug. Bezahlt und gespeichert wird erst beim Übernehmen.</p><p class="'+(s.money<quote.total?'negative':'')+'">'+(s.money<quote.total?'Nicht genug Bargeld · ':'Bargeld · ')+euro(s.money)+'</p><footer class="tuning-actions"><div class="button-row">'+button('VORSCHAU','tuningPreview','','secondary')+button('ABBRECHEN','close','','secondary')+'</div>'+button('ÜBERNEHMEN · '+euro(quote.total),'tuningConfirm','','primary',!quote.total||s.money<quote.total)+'</footer></section>';
}
